<?php namespace Workspace; ?>
<section class="panel"><div class="panelhead"><h2>Вызовы AI за 30 суток</h2><a href="<?= h(url('assistant')) ?>" target="_blank" rel="noopener">Открыть журнал в отдельной вкладке</a></div>
<p class="inset">Для отмены выполняющегося запроса обновите журнал в другой вкладке. Отмена прекращает ожидание и не гарантирует остановку вычислений или списаний у OpenAI. Стоимость — оценка по настроенному тарифу, без скидки за кэш. Дневной лимит: <?= h($ops['cap']===null?'не задан':($ops['cap']/1000000).' USD') ?>.</p>
<?php foreach($ops['own'] as $r): ?><div class="inset"><b><?= h(gmdate('Y-m-d H:i:s',(int)$r['started_at'])) ?> UTC · <?= h($r['operation']) ?> · <?= h($r['model']) ?></b><p><?= h($r['status']) ?> · <?= h($r['latency_ms']??'—') ?> ms · токены <?= h($r['input_tokens']??'—') ?>/<?= h($r['output_tokens']??'—') ?> · <?= h($r['cost_micro']===null?'стоимость неизвестна':($r['cost_micro']/1000000).' USD') ?><?php if($r['retry_until']!==null): ?> · пауза до <?= h(gmdate('H:i:s',(int)$r['retry_until'])) ?> UTC<?php endif ?></p>
<?php if($r['status']==='running'): ?><form method="post" action="<?= h(url('assistant')) ?>"><?php formFields('ai.cancel') ?><input type="hidden" name="handle" value="<?= h($r['handle']) ?>"><button <?= (int)$r['cancel_requested']?'disabled':'' ?>><?= (int)$r['cancel_requested']?'Отмена запрошена':'Отменить вызов' ?></button></form><?php elseif($r['status']==='ok'): ?><form method="post" class="inline" action="<?= h(url('assistant')) ?>"><?php formFields('ai.rate') ?><input type="hidden" name="handle" value="<?= h($r['handle']) ?>"><span>Качество: <?= h($r['quality']===null?'не оценено':((int)$r['quality']?'полезно':'неполезно')) ?></span><button name="quality" value="1">Полезно и корректно</button><button name="quality" value="0">Ошибка или неполнота</button></form><?php endif ?></div><?php endforeach ?>
<?php if($user['role']==='owner'): ?><h3 class="inset">Метрики по проектным ролям</h3><?php if(!mfaFresh()): ?><p class="inset"><a href="<?= h(url('security')) ?>">Подтвердите MFA</a></p><?php endif ?><?php foreach($ops['roles'] as $role=>$r): ?><div class="splitrow"><b><?= h($role) ?></b><span>Вызовы <?= h($r['calls']) ?>; успешные <?= h($r['ok']) ?>; положительные оценки <?= h($r['positive']) ?>/<?= h($r['rated']) ?>; p95 <?= h($r['p95']??'—') ?> ms; известная стоимость <?= h($r['known_micro']/1000000) ?> USD; неизвестно <?= h($r['unknown']) ?></span></div><?php endforeach ?><?php endif ?></section>
<?php if(isset($delegation)): ?><section class="panel"><div class="panelhead"><h2>Чтение проекта из ChatGPT</h2></div><p class="inset">Делегирование: <?= $delegation['enabled']?'разрешено':'запрещено' ?>. Только задачи, вехи и выпуски, без финансов, договоров и действий записи. Требуется MFA при выдаче. Срок токена 15 минут.</p><?php if($user['role']==='owner'): ?><form class="inset" method="post" action="<?= h(url('assistant')) ?>"><?php formFields('ai.chatgpt.policy') ?><button name="enabled" value="<?= $delegation['enabled']?'0':'1' ?>"><?= $delegation['enabled']?'Отключить и отозвать все токены':'Разрешить делегирование' ?></button></form><?php endif ?><form class="inset" method="post" action="<?= h(url('assistant')) ?>"><?php formFields('ai.chatgpt.revoke') ?><button>Отозвать мой доступ ChatGPT</button></form></section><?php endif ?>
